# TEST: T0188
#
# Checks the compilation database compile_commands.json generated by 'make'
# (target compile_cmd, config/compile_commands.sh) against the current build
# configuration.  Run by test/run-tests.sh; the expected values are passed by
# 'make check' in the environment:
#
#   TOP              top-level directory (the database is TOP/compile_commands.json)
#   CDB_SOURCES      C++ sources that must have exactly one entry
#   CDB_COMPILER     compiler (CXX)
#   CDB_BUILD_DIR    build directory (build.dir)
#   LLVM_MAJOR       major version of the selected LLVM
#   LLVM_INCLUDEDIR  include directory of the selected LLVM
#
# Exit status 0: database is valid; 77: not run by 'make check'; 1: errors.

use strict;
use warnings;
use JSON::PP;

for my $var (qw(TOP CDB_SOURCES CDB_COMPILER CDB_BUILD_DIR LLVM_MAJOR
                LLVM_INCLUDEDIR)) {
    if (!defined $ENV{$var} || $ENV{$var} eq '') {
	print "requires 'make check' (environment variable $var not set)\n";
	exit 77;
    }
}

my $top = $ENV{TOP};
my $file = "$top/compile_commands.json";
my @error;

open my $fh, '<', $file or do { print "can not open $file: $!\n"; exit 1 };
my $text = do { local $/; <$fh> };
close $fh;

my $db = eval { JSON::PP->new->decode($text) };
if (!$db) {
    print "$file: invalid JSON: $@";
    exit 1;
}
if (ref $db ne 'ARRAY' || !@$db) {
    print "$file: expected a non-empty JSON array\n";
    exit 1;
}

my %expected = map { $_ => 1 } split ' ', $ENV{CDB_SOURCES};
my %seen;
for my $i (0 .. $#$db) {
    my $e = $db->[$i];
    my $where = "entry $i";
    if (ref $e ne 'HASH') {
	push @error, "$where: not a JSON object";
	next;
    }
    for my $key (qw(directory file arguments)) {
	push @error, "$where: missing '$key'" unless exists $e->{$key};
    }
    next if grep { !exists $e->{$_} } qw(directory file arguments);

    my ($dir, $path, $args) = @$e{qw(directory file arguments)};
    push @error, "$where: directory '$dir' is not $top" if $dir ne $top;
    push @error, "$where: directory '$dir' does not exist" unless -d $dir;
    if (ref $args ne 'ARRAY' || !@$args || grep { ref $_ } @$args) {
	push @error, "$where: 'arguments' is not a non-empty array of strings";
	next;
    }
    (my $src = $path) =~ s{^\Q$dir\E/}{};
    $where = "entry for $src";
    push @error, "$where: file '$path' does not exist" unless -f $path;
    push @error, "$where: unexpected source file" unless $expected{$src};
    push @error, "$where: duplicate entry" if $seen{$src}++;

    my $obj = "$ENV{CDB_BUILD_DIR}$src";
    $obj =~ s/\.cpp$/.o/;
    push @error, "$where: compiler is '$args->[0]', expected '$ENV{CDB_COMPILER}'"
        if $args->[0] ne $ENV{CDB_COMPILER};
    push @error, "$where: last argument is not the source file"
        if $args->[-1] ne $src;
    push @error, "$where: missing '-c'" unless grep { $_ eq '-c' } @$args;
    push @error, "$where: missing '-DLLVM_MAJOR_VERSION=$ENV{LLVM_MAJOR}'"
        unless grep { $_ eq "-DLLVM_MAJOR_VERSION=$ENV{LLVM_MAJOR}" } @$args;
    my $inc = $ENV{LLVM_INCLUDEDIR};
    push @error, "$where: missing LLVM include directory '$inc'"
        unless grep { $args->[$_] eq "-I$inc"
                      || ($args->[$_] eq '-I' && ($args->[$_ + 1] // '') eq $inc) }
                    0 .. $#$args;
    my ($o) = grep { $args->[$_] eq '-o' } 0 .. $#$args;
    push @error, "$where: output is not '$obj'"
        unless defined $o && ($args->[$o + 1] // '') eq $obj
               && ($e->{output} // '') eq $obj;
}
for my $src (sort keys %expected) {
    push @error, "no entry for $src" unless $seen{$src};
}

print "$_\n" for @error;
print scalar(@$db), " entries checked\n" unless @error;
exit(@error ? 1 : 0);
